class Solution:
    def canBeSortedByRightShift(self, arr: List[int]) -> bool:
        # Check if the array is empty or has only one element, in which case it is always sorted
        if len(arr) <= 1:
            return True

        # Count the number of times elements are smaller than the next element
        changes_needed = 0

        for i in range(len(arr)):
            if arr[i] < arr[(i + 1) % len(arr)]:
                changes_needed += 1

        # If there are more than one change needed, it's impossible to make the array sorted
        return changes_needed > 1

